//Approach 1: Using memoization. TC: O(m*n) SC: O(m*n).
class Solution {
public:
    vector<vector<int>> dp;
    vector<vector<int>> dir={{1,0},{0,1},{-1,0},{0,-1}};
    int m,n,ans;
    int solve(vector<vector<int>> &matrix,int i,int j)
    {
        if(dp[i][j])
            return dp[i][j];
        dp[i][j]=1;
        for(int k=0;k<4;k++)
        {
            int dx=i+dir[k][0];
            int dy=j+dir[k][1];
            if(dx<0 or dx>=m or dy<0 or dy>=n or matrix[dx][dy]<=matrix[i][j])
                continue;
            dp[i][j]=max(dp[i][j],1+solve(matrix,dx,dy));
        }
        return dp[i][j];
    }
    int longestIncreasingPath(vector<vector<int>>& matrix) {
        m=matrix.size();
        n=matrix[0].size();
        dp.resize(m,vector<int>(n));
        ans=0;
        for(int i=0;i<m;i++)
        {
            for(int j=0;j<n;j++)
                ans=max(ans,solve(matrix,i,j));
        }
        return ans;
    }
};

class Solution(object):

    def longestIncreasingPath(self, matrix):

        """

        :type matrix: List[List[int]]

        :rtype: int

        """

        self.dp = {}

        def dp(x, y):

            if (x, y) not in self.dp:

                self.dp[(x, y)] = 1+max(

                    dp(x+1, y) if x+1<len(matrix) and matrix[x+1][y]<matrix[x][y] else 0,

                    dp(x-1, y) if x>0 and matrix[x-1][y]<matrix[x][y] else 0,

                    dp(x, y+1) if y+1<len(matrix[0]) and matrix[x][y+1]<matrix[x][y] else 0,

                    dp(x, y-1) if y>0 and matrix[x][y-1]<matrix[x][y] else 0

                )

            return self.dp[(x, y)]

        m = 0

        for i, row in enumerate(matrix):

            for j, c in enumerate(row):

                m = max(m, dp(i, j))

        return m
